SELECT DATE_TRUNC('MONTH', order_date) AS order_month, channel, status, SUM(CASE WHEN status = 'SHIPPED' THEN 1 ELSE 0 END) AS shipped_count, MAX(amount) AS max_amount, ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_returned FROM orders WHERE discount > 0.23 AND YEAR(order_date) >= 2024 AND discount <= 0.27 GROUP BY DATE_TRUNC('MONTH', order_date), channel, status;
